package org.eclipse.kura.openapi;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.Set;

import org.eclipse.kura.configuration.metatype.OCD;
import org.eclipse.kura.configuration.metatype.Scalar;
import org.eclipse.kura.rest.configuration.api.ComponentConfigurationDTO;
import org.eclipse.kura.rest.configuration.api.ComponentConfigurationList;
import org.eclipse.kura.rest.configuration.api.OcdDTO;
import org.eclipse.kura.rest.configuration.api.PropertyDTO;
import org.eclipse.kura.rest.system.dto.FilterDTO;
import org.eclipse.kura.rest.system.dto.FrameworkPropertiesDTO;
import org.eclipse.kura.system.SystemService;
import org.eclipse.kura.system.InternetConnectionStatus;
import org.junit.Test;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.google.gson.Gson;
import com.networknt.schema.JsonSchemaFactory;
import com.networknt.schema.SpecVersion;
import com.networknt.schema.ValidationMessage;

import io.swagger.v3.core.util.Json;

public class GsonSchemaTest {

    private JsonNode document;
    private Object dto;
    private String schemaName;
    private JsonNode payload;
    private Set<ValidationMessage> errors;

    @Test
    public void privateFieldsMatchTheResponseSchema() throws Exception {
        givenGeneratedSchemas();
        givenFrameworkProperties(false);

        whenPayloadIsValidated();

        thenPayloadIsValid();
        thenPrivateFieldsAreDocumented();
    }

    @Test
    public void filteredResponsesAllowOmittedFields() throws Exception {
        givenGeneratedSchemas();
        givenFrameworkProperties(true);

        whenPayloadIsValidated();

        thenPayloadIsValid();
        thenOnlyRequestedPropertyIsPresent();
    }

    @Test
    public void wrongFieldTypesAreRejected() throws Exception {
        givenGeneratedSchemas();
        givenInvalidFrameworkProperties();

        whenPayloadIsValidated();

        thenPayloadIsRejected();
    }

    @Test
    public void filtersMatchTheRequestSchema() throws Exception {
        givenGeneratedSchemas();
        givenFilter();

        whenPayloadIsValidated();

        thenPayloadIsValid();
        thenFilterFieldsAreDocumented();
    }

    @Test
    public void nestedConfigurationAllowsDynamicValues() throws Exception {
        givenGeneratedSchemas();
        givenConfiguration();

        whenPayloadIsValidated();

        thenPayloadIsValid();
        thenDefinitionUsesTheSerializedFieldType();
    }

    private void givenGeneratedSchemas() throws Exception {
        this.document = Json.mapper().readTree(Files.readString(
                Path.of(System.getProperty("openapi.directory"), "openapi.json")));
    }

    private void givenFrameworkProperties(boolean filtered) {
        final SystemService system = mock(SystemService.class);
        when(system.getDeviceName()).thenReturn("test-gateway");
        when(system.getInternetConnectionStatus()).thenReturn(InternetConnectionStatus.FULL);
        when(system.getProperties()).thenReturn(new Properties());
        this.dto = filtered ? new FrameworkPropertiesDTO(system, List.of("deviceName")) : new FrameworkPropertiesDTO(system);
        this.schemaName = "FrameworkPropertiesDTO";
    }

    private void givenInvalidFrameworkProperties() {
        this.dto = Map.of("deviceName", 42);
        this.schemaName = "FrameworkPropertiesDTO";
    }

    private void givenFilter() {
        final FilterDTO filter = new FilterDTO();
        filter.getNames().add("deviceName");
        filter.getGroupNames().add("hardware");
        this.dto = filter;
        this.schemaName = "FilterDTO";
    }

    private void givenConfiguration() {
        final OCD definition = mock(OCD.class);
        when(definition.getId()).thenReturn("test.component");
        when(definition.getName()).thenReturn("Test component");
        this.dto = new ComponentConfigurationList(List.of(new ComponentConfigurationDTO("test.component",
                new OcdDTO(definition), Map.of(
                        "enabled", new PropertyDTO(true, Scalar.BOOLEAN),
                        "count", new PropertyDTO(3, Scalar.INTEGER),
                        "labels", new PropertyDTO(List.of("one", "two"), Scalar.STRING)))));
        this.schemaName = "ComponentConfigurationList";
    }

    private void whenPayloadIsValidated() throws Exception {
        this.payload = Json.mapper().readTree(new Gson().toJson(this.dto));
        final ObjectNode schema = Json.mapper().createObjectNode();
        schema.put("$ref", "#/components/schemas/" + this.schemaName);
        schema.set("components", this.document.path("components"));
        this.errors = JsonSchemaFactory.getInstance(SpecVersion.VersionFlag.V4).getSchema(schema).validate(this.payload);
    }

    private void thenPayloadIsValid() {
        assertTrue(this.errors.toString(), this.errors.isEmpty());
    }

    private void thenPayloadIsRejected() {
        assertFalse(this.errors.isEmpty());
    }

    private void thenPrivateFieldsAreDocumented() {
        this.payload.fieldNames().forEachRemaining(name -> assertTrue(name,
                this.document.at("/components/schemas/FrameworkPropertiesDTO/properties").has(name)));
        assertEquals("string", this.document.at("/components/schemas/FrameworkPropertiesDTO/properties/deviceName/type").asText());
    }

    private void thenOnlyRequestedPropertyIsPresent() {
        assertEquals(1, this.payload.size());
        assertEquals("test-gateway", this.payload.path("deviceName").asText());
    }

    private void thenFilterFieldsAreDocumented() {
        assertEquals("array", this.document.at("/components/schemas/FilterDTO/properties/names/type").asText());
        assertEquals("array", this.document.at("/components/schemas/FilterDTO/properties/groupNames/type").asText());
    }

    private void thenDefinitionUsesTheSerializedFieldType() {
        assertEquals("#/components/schemas/OcdDTO",
                this.document.at("/components/schemas/ComponentConfigurationDTO/properties/definition/$ref").asText());
    }
}
